INSERT INTO Language_en_US(Tag,Text) VALUES
 ('TXT_KEY_CWC3_MAKURIA_CIV','Kingdom of Makuria'),
 ('TXT_KEY_CWC3_MAKURIA_SHORT','Kingdom of Makuria'),
 ('TXT_KEY_CWC3_MAKURIA_ADJECTIVE','Makurian'),
 ('TXT_KEY_CWC3_MAKURIA_LEADER','Merkurios'),
 ('TXT_KEY_CWC3_MAKURIA_TRAIT','The Walls of Dongola'),
 ('TXT_KEY_CWC3_MAKURIA_TRAIT_HELP','Each owned city possessing a Walls BuildingClass building, including a unique replacement or free Walls, gains +1 Culture and +1 Faith. The condition counts once per city.'),
 ('TXT_KEY_CWC3_MAKURIA_CIV_PEDIA','Makuria was a medieval Christian Nubian kingdom centered on Old Dongola. Its churches and painted religious art provide the historical setting for this civilization. Merkurios leads its defense and cultural patronage; the bonus values are game abstractions.'),
 ('TXT_KEY_CWC3_MAKURIA_STRATEGY','Build Walls where you settle and combine their Faith and Culture with Painted Churches. Protect these investments with watchful Bowmen; turn religious infrastructure into cultural influence.'),
 ('TXT_KEY_CWC3_MAKURIA_LEADER_PEDIA','Makuria was a medieval Christian Nubian kingdom centered on Old Dongola. Its churches and painted religious art provide the historical setting for this civilization. Merkurios leads its defense and cultural patronage; the bonus values are game abstractions.'),
 ('TXT_KEY_CWC3_MAKURIA_DAWN','Merkurios, guide Kingdom of Makuria. Build Walls where you settle and combine their Faith and Culture with Painted Churches. Protect these investments with watchful Bowmen; turn religious infrastructure into cultural influence.'),
 ('TXT_KEY_CWC3_MAKURIA_UNIT','Nubian Bowman'),
 ('TXT_KEY_CWC3_MAKURIA_UNIT_HELP','Replaces the active CP Composite Bowman. +1 Sight and +15% defensive Combat Strength, including defense against ranged attacks. No offensive strength bonus. Promotion persists through upgrades.'),
 ('TXT_KEY_CWC3_MAKURIA_UNIT_PEDIA','Makuria was a medieval Christian Nubian kingdom centered on Old Dongola. Its churches and painted religious art provide the historical setting for this civilization. Merkurios leads its defense and cultural patronage; the bonus values are game abstractions. +1 Sight and +15% defensive Combat Strength, including defense against ranged attacks. No offensive strength bonus. Promotion persists through upgrades.'),
 ('TXT_KEY_CWC3_MAKURIA_UNIT_STRATEGY','+1 Sight and +15% defensive Combat Strength, including defense against ranged attacks. No offensive strength bonus. Promotion persists through upgrades. Preserves all other active CP unit properties and companions.'),
 ('TXT_KEY_CWC3_MAKURIA_BUILDING','Painted Church'),
 ('TXT_KEY_CWC3_MAKURIA_BUILDING_HELP','Replaces the active CP Temple. +1 Culture and +1 Science beyond every inherited active Temple effect.'),
